episode.remediation_sql:
WITH counts AS (
  SELECT uuid, COUNT(*) AS cnt
  FROM rulings
  GROUP BY uuid
), maxcnt AS (
  SELECT MAX(cnt) AS m FROM counts
), top AS (
  SELECT uuid FROM counts WHERE cnt = (SELECT m FROM maxcnt)
)
SELECT c.name, c.artist, MAX(c.isPromo) AS isPromo
FROM cards c
JOIN top t ON c.uuid = t.uuid
GROUP BY c.name, c.artist;

